const items = $input.all();
const results = [];
for (const item of items) {
  const body = item.json.body || item.json;
  results.push({
    json: {
      question: body.question || 'Default Poll Question',
      options: body.options || ['Option A', 'Option B', 'Option C'],
      chatId: body.chatId || '',
      isAnonymous: body.isAnonymous !== false,
      pollId: `poll_${Date.now()}`,
      createdAt: new Date().toISOString()
    }
  });
}
return results;

const items = $input.all();
const results = [];
for (const item of items) {
  const poll = item.json.poll || {};
  const options = (poll.options || []).map(o => ({
    text: o.text,
    votes: o.voter_count
  }));
  const totalVotes = options.reduce((sum, o) => sum + o.votes, 0);
  results.push({
    json: {
      pollId: poll.id,
      question: poll.question,
      options,
      totalVotes,
      isClosed: poll.is_closed,
      timestamp: new Date().toISOString()
    }
  });
}
return results;

const items = $input.all();
const item = items[0].json;
let text = `📊 <b>Poll Results: ${item.question}</b>\n\n`;
const options = Array.isArray(item.options) ? item.options : JSON.parse(item.options || '[]');
options.forEach(o => {
  const pct = item.totalVotes > 0 ? Math.round((o.votes / item.totalVotes) * 100) : 0;
  const bar = '█'.repeat(Math.round(pct / 10)) + '░'.repeat(10 - Math.round(pct / 10));
  text += `${o.text}: ${bar} ${pct}% (${o.votes})\n`;
});
text += `\n👥 Total votes: ${item.totalVotes}`;
return [{ json: { text } }];
